rcore 1; package settings version "1";
metamodel "urn:inferred:settings" prefix p {
 class Item { attr backing: String [0,1]; attr computed: String [0,1] derived; }
}

grammar contexts.settings.Language hidden(WS)
generate model "urn:contexts:settings"
import "urn:inferred:settings" as p
import "http://www.eclipse.org/emf/2002/Ecore" as ecore
Model: 'computed' child=Item<true> | 'stored' child=Item<false>;
Item<Flag> returns p::Item: <Flag> computed=ID | <!Flag> backing=ID;
terminal ID: ('a'..'z')+;
terminal WS: (' '|'\t'|'\r'|'\n')+;
terminal ANY_OTHER: .;

